package com.casystem.onboarding.controller;
import com.casystem.onboarding.repository.PostalCodeRepository;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;import java.util.*;
@RestController @RequestMapping("/api/location") @CrossOrigin(origins="*") public class LocationController{private final PostalCodeRepository postal;private final RestClient http=RestClient.create();private static final List<String> STATES=List.of("Aguascalientes","Baja California","Baja California Sur","Campeche","Chiapas","Chihuahua","Ciudad de México","Coahuila de Zaragoza","Colima","Durango","Estado de México","Guanajuato","Guerrero","Hidalgo","Jalisco","Michoacán de Ocampo","Morelos","Nayarit","Nuevo León","Oaxaca","Puebla","Querétaro","Quintana Roo","San Luis Potosí","Sinaloa","Sonora","Tabasco","Tamaulipas","Tlaxcala","Veracruz de Ignacio de la Llave","Yucatán","Zacatecas");public LocationController(PostalCodeRepository p){postal=p;}@GetMapping("/states")public List<String> states(){return STATES;}@GetMapping("/municipalities")public List<String> municipalities(@RequestParam String state){return postal.municipalities(state);}@GetMapping("/postal-code/{cp}")public Map<String,Object> postalCode(@PathVariable String cp){if(!cp.matches("\\d{5}"))throw new IllegalArgumentException("El código postal debe tener 5 dígitos");var rows=postal.find(cp);if(!rows.isEmpty())return result(cp,rows);try{Map<?,?>root=http.get().uri("https://sepomex.nitrostudio.com.mx/api/latest/cp/{cp}.json",cp).retrieve().body(Map.class);Object d=root==null?null:root.get("data");if(d instanceof Map<?,?>data&&data.get("postcodes") instanceof List<?>posts){List<Map<String,Object>> r=new ArrayList<>();for(Object o:posts)if(o instanceof Map<?,?>m)r.add(Map.of("state",Objects.toString(m.get("d_estado"),""),"municipality",Objects.toString(m.get("d_mnpio"),""),"settlement",Objects.toString(m.get("d_asenta"),"")));if(!r.isEmpty())return result(cp,r);}}catch(Exception ignored){}return Map.of("postalCode",cp,"found",false,"state","","municipality","","settlements",List.of(),"message","No encontramos el código postal. Puedes completar Estado, Municipio y Colonia manualmente.");}private Map<String,Object> result(String cp,List<Map<String,Object>> rows){String st=Objects.toString(rows.get(0).get("state"),""),mu=Objects.toString(rows.get(0).get("municipality"),"");LinkedHashSet<String>s=new LinkedHashSet<>();rows.forEach(x->{String v=Objects.toString(x.get("settlement"),"");if(!v.isBlank())s.add(v);});return Map.of("postalCode",cp,"found",true,"state",st,"municipality",mu,"settlements",new ArrayList<>(s));}}
